package com.onecall.archtests.container;

import static org.assertj.core.api.Assertions.*;
import static com.onecall.archtests.container.CustomerBusinessNumbersFixture.execute;
import static com.onecall.archtests.container.OperationsIvrSessionReadFixture.one;

import java.sql.SQLException;
import java.util.*;
import org.junit.jupiter.api.*;

public class OperationsCatalogDraftRoleLeastPrivilegeIT {
    static final OperationsCatalogDraftFixture fixture = new OperationsCatalogDraftFixture();
    @BeforeAll static void start() throws Exception { fixture.start(); }
    @AfterAll static void stop() { fixture.close(); }
    @BeforeEach void reset() throws Exception { fixture.reset(); }
    @AfterEach void clean() throws Exception { fixture.clean(); }
    void denied(String role, String sql, String state) throws Exception { try (var connection = fixture.base.shared.runtime()) { connection.setAutoCommit(false); execute(connection, "SET LOCAL ROLE " + role); assertThatThrownBy(() -> execute(connection, sql)).isInstanceOfSatisfying(SQLException.class, failure -> assertThat(failure.getSQLState()).isEqualTo(state)); connection.rollback(); } }
    @Test void runtimeLoginUsesOnlyExistingSettableNonInheritedOwnerRoles() throws Exception { try (var connection = fixture.admin()) { assertThat(one(connection, "SELECT string_agg(r.rolname||':'||m.admin_option||':'||m.inherit_option||':'||m.set_option,',' ORDER BY r.rolname) FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.roleid WHERE m.member=?::regrole", fixture.base.shared.login)).isEqualTo("catalog_order_role:false:false:true,operations_iam_role:false:false:true"); assertThat(one(connection, "SELECT rolsuper OR rolinherit OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls FROM pg_roles WHERE rolname=?", fixture.base.shared.login)).isEqualTo("f"); } for (String role : List.of("operations_iam_role", "catalog_order_role")) try (var connection = fixture.base.shared.runtime()) { connection.setAutoCommit(false); execute(connection, "SET LOCAL ROLE " + role); assertThat(one(connection, "SELECT current_user")).isEqualTo(role); connection.rollback(); assertThat(one(connection, "SELECT current_user")).isEqualTo(fixture.base.shared.login); } }
    @Test void v004EffectiveCatalogAclRemainsExactlyFortyTwoTuples() throws Exception {
        var actual = new TreeSet<String>();
        try (var connection = fixture.admin(); var statement = connection.createStatement(); var rows = statement.executeQuery("""
            WITH objects AS (
              SELECT 'table' kind,c.relname identity,'' column_name,c.relacl acl FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='catalog_order' AND c.relkind='r'
              UNION ALL SELECT 'column',c.relname,a.attname,a.attacl FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='catalog_order' AND a.attnum>0 AND NOT a.attisdropped
              UNION ALL SELECT 'routine',p.proname,'',p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='catalog_order'
              UNION ALL SELECT 'schema',nspname,'',nspacl FROM pg_namespace WHERE nspname='catalog_order'
            ) SELECT kind||'|'||identity||'|'||column_name||'|'||privilege_type||'|'||grantor::regrole::text||'|'||is_grantable FROM objects CROSS JOIN LATERAL aclexplode(acl) grants WHERE grantee='catalog_order_role'::regrole ORDER BY 1
            """)) { while (rows.next()) actual.add(rows.getString(1)); }
        var expected = new TreeSet<String>(); String suffix = "|catalog_order_owner|false";
        for (String table : List.of("catalog_product", "catalog_version", "catalog_offer", "catalog_benefit_line", "customer_order", "payment_order", "payment_event")) for (String privilege : List.of("SELECT", "INSERT")) expected.add("table|" + table + "||" + privilege + suffix);
        Map.of("catalog_version", List.of("sale_status", "offer_type", "audience", "price_cents", "currency", "billing_cycle", "installments", "grant_interval_months", "snapshot", "snapshot_sha256", "published_at", "revision"), "catalog_offer", List.of("offer_status", "version_token", "revision"), "customer_order", List.of("payment_status", "paid_at", "closed_at", "revision"), "payment_order", List.of("status", "provider_transaction_id", "updated_at", "revision")).forEach((table, columns) -> columns.forEach(column -> expected.add("column|" + table + "|" + column + "|UPDATE" + suffix)));
        for (String routine : List.of("guard_catalog_version_published", "guard_catalog_offer", "guard_customer_order_snapshot", "guard_payment_order_identity")) expected.add("routine|" + routine + "||EXECUTE" + suffix);
        expected.add("schema|catalog_order||USAGE" + suffix); assertThat(actual).hasSize(42).isEqualTo(expected);
        assertThat(fixture.value("SELECT has_function_privilege('catalog_order_role','audit.append_fact(timestamp with time zone,text,uuid,text,text,uuid,text,jsonb,jsonb,text,text)','EXECUTE')")).isEqualTo("t");
    }
    @Test void laterMigrationsAndProvisioningRetainExactEffectiveAclOracle() throws Exception { fixture.provisioningOracle(); assertThat(fixture.value("SELECT count(*) FROM public.flyway_schema_history WHERE success AND version IS NOT NULL")).isEqualTo("19"); assertThat(fixture.value("SELECT count(*) FROM public.flyway_schema_history WHERE version='019'")).isEqualTo("1"); }
    @Test void authorityReadsOnlyCurrentEmployeeColumnsOnOwnerConnection() throws Exception { fixture.draft(true); var reads = fixture.calls("FROM operations_iam.employee_account"); assertThat(reads).hasSize(1); assertThat(reads.getFirst().sql()).isEqualTo("SELECT id, status, role, revision FROM operations_iam.employee_account WHERE id = ?"); assertThat(reads.getFirst().role()).isEqualTo("operations_iam_role"); denied("catalog_order_role", "SELECT id,status,role,revision FROM operations_iam.employee_account", "42501"); }
    @Test void createAndReplaceUseExactLocalRoleSequenceAndWitness() throws Exception { UUID version = fixture.draft(true); witness(); assertThat(fixture.value("SELECT created_by_employee_id FROM catalog_order.catalog_version WHERE id=?", version)).isEqualTo(fixture.base.shared.employee.toString()); fixture.entries.clear(); fixture.success(fixture.replace(version, 1, 5), 200); witness(); assertThat(fixture.entries).filteredOn(entry -> entry.sql().startsWith("UPDATE") || entry.sql().contains("audit.append_fact")).allSatisfy(entry -> assertThat(entry.role()).isEqualTo("catalog_order_role")); fixture.noPlatformWrites(); }
    void witness() { var switches = fixture.calls("SET LOCAL ROLE"); assertThat(switches).extracting(OperationsCatalogVersionLifecycleFixture.Entry::sql).containsExactly("SET LOCAL ROLE operations_iam_role", "SET LOCAL ROLE catalog_order_role", "SET LOCAL ROLE NONE"); assertThat(fixture.entries).extracting(OperationsCatalogVersionLifecycleFixture.Entry::pid).containsOnly(switches.getFirst().pid()); assertThat(fixture.entries).extracting(OperationsCatalogVersionLifecycleFixture.Entry::transaction).containsOnly(switches.getFirst().transaction()); assertThat(switches.getLast().role()).isEqualTo(fixture.base.shared.login); }
    @Test void missingInactiveAndNonAdminAuthorityCannotMutate() throws Exception { UUID product = fixture.product(); String before = fixture.allFacts(); for (String token : List.of("missing", "disabled", "ops")) { fixture.entries.clear(); fixture.problem(fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, 1, true), token), token.equals("missing") ? 503 : 403, token.equals("missing") ? "SERVICE_UNAVAILABLE" : "FORBIDDEN"); assertThat(fixture.calls("SET LOCAL ROLE")).extracting(OperationsCatalogVersionLifecycleFixture.Entry::sql).containsExactly("SET LOCAL ROLE operations_iam_role", "SET LOCAL ROLE NONE"); } assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void forbiddenIdentityBenefitAndForeignWritesAreDenied() throws Exception { fixture.draft(true); for (String sql : List.of("UPDATE catalog_order.catalog_version SET product_id=product_id", "UPDATE catalog_order.catalog_version SET version_no=version_no", "UPDATE catalog_order.catalog_version SET created_by_employee_id=created_by_employee_id", "UPDATE catalog_order.catalog_version SET created_at=created_at", "UPDATE catalog_order.catalog_benefit_line SET quantity=quantity", "DELETE FROM catalog_order.catalog_version", "DELETE FROM catalog_order.catalog_benefit_line", "UPDATE catalog_order.catalog_offer SET channel=channel", "INSERT INTO audit.audit_fact(id) VALUES(gen_random_uuid())", "INSERT INTO platform.outbox_event(id) VALUES(gen_random_uuid())", "UPDATE operations_iam.employee_account SET revision=revision+1")) denied("catalog_order_role", sql, "42501"); }
    @Test void publishedAndAppendOnlyTriggersRejectForbiddenChanges() throws Exception { UUID version = fixture.draft(true); fixture.base.success(fixture.base.request(version, true, null, 1)); for (String sql : List.of("UPDATE catalog_order.catalog_version SET price_cents=9 WHERE id='" + version + "'", "UPDATE catalog_order.catalog_product SET product_family='OTHER'", "UPDATE catalog_order.catalog_benefit_line SET quantity=quantity+1", "DELETE FROM catalog_order.catalog_benefit_line", "UPDATE catalog_order.catalog_offer SET channel='OTHER'")) try (var connection = fixture.admin()) { assertThatThrownBy(() -> execute(connection, sql)).isInstanceOfSatisfying(SQLException.class, failure -> assertThat(failure.getSQLState()).isEqualTo("P0001")); } }
    @Test void naturalAndChildUniqueConstraintsAndDefaultsHold() throws Exception { UUID version = fixture.draft(true); assertThat(fixture.value("SELECT sale_status||':'||revision||':'||(published_at IS NULL) FROM catalog_order.catalog_version WHERE id=?", version)).isEqualTo("DRAFT:1:true"); for (String table : List.of("catalog_version", "catalog_benefit_line", "catalog_offer")) try (var connection = fixture.admin()) { assertThatThrownBy(() -> execute(connection, "INSERT INTO catalog_order." + table + " SELECT * FROM catalog_order." + table)).isInstanceOfSatisfying(SQLException.class, failure -> assertThat(failure.getSQLState()).isEqualTo("23505")); } assertThat(fixture.value("SELECT count(*) FROM pg_constraint WHERE connamespace='catalog_order'::regnamespace AND conname IN ('uq_catalog_version_no','uq_catalog_benefit_version_type','uq_catalog_offer_version_channel')")).isEqualTo("3"); }
    @Test void readOnlyWrongRoleAndMissingAuditCapabilityFailClosed() throws Exception { UUID product = fixture.product(); try (var connection = fixture.base.shared.runtime()) { connection.setReadOnly(true); connection.setAutoCommit(false); execute(connection, "SET LOCAL ROLE catalog_order_role"); assertThatThrownBy(() -> execute(connection, "UPDATE catalog_order.catalog_version SET revision=revision+1")).isInstanceOfSatisfying(SQLException.class, failure -> assertThat(failure.getSQLState()).isEqualTo("25006")); connection.rollback(); } denied("operations_iam_role", "UPDATE catalog_order.catalog_version SET revision=revision+1", "42501"); String before = fixture.allFacts(); try { try (var connection = fixture.admin()) { execute(connection, "SET ROLE audit_owner"); execute(connection, "REVOKE EXECUTE ON FUNCTION audit.append_fact(timestamptz,text,uuid,text,text,uuid,text,jsonb,jsonb,text,text) FROM catalog_order_role"); } fixture.problem(fixture.create(product, 1, true), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); } finally { try (var connection = fixture.admin()) { execute(connection, "SET ROLE audit_owner"); execute(connection, "GRANT EXECUTE ON FUNCTION audit.append_fact(timestamptz,text,uuid,text,text,uuid,text,jsonb,jsonb,text,text) TO catalog_order_role"); } } }
    @Test void restorationRollbackAndPoolReuseLeaveNoDirtyRoleOrWitness() throws Exception { UUID product = fixture.product(); String before = fixture.allFacts(); for (String stage : List.of("RESTORE", "TERMINATE")) { fixture.fail(stage); fixture.problem(fixture.create(product, 1, true), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); fixture.clean(); } fixture.entries.clear(); fixture.success(fixture.create(product, 1, true), 201); witness(); }
    @Test void lockTimeoutsTerminatedConnectionsAndOverflowNeverPartiallyCommit() throws Exception {
        UUID product = fixture.product(); var createRace = fixture.race(() -> fixture.create(product, 1, true), () -> fixture.create(product, 1, true), true, false); UUID version = UUID.fromString(fixture.success(createRace.winner(), 201).get("catalogVersionId").asString()); fixture.problem(createRace.contender(), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(createRace.expired()).isTrue(); assertThat(fixture.states).contains("55P03"); var replaceRace = fixture.race(() -> fixture.replace(version, 1, 4), () -> fixture.replace(version, 1, 4), true, false); fixture.success(replaceRace.winner(), 200); fixture.problem(replaceRace.contender(), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(replaceRace.expired()).isTrue(); assertThat(fixture.states).contains("55P03");
        for (String fault : List.of("STATEMENT_TIMEOUT", "TERMINATE")) { String before = fixture.allFacts(); fixture.fail(fault); fixture.problem(fixture.replace(version, 2, 9), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); fixture.clean(); } assertThat(fixture.states).contains("57014");
        fixture.mutate("UPDATE catalog_order.catalog_offer SET revision=2147483647 WHERE catalog_version_id=?", version); String before = fixture.allFacts(); fixture.problem(fixture.replace(version, 2, 9), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before);
        fixture.mutate("UPDATE catalog_order.catalog_version SET revision=2147483647 WHERE id=?", version); before = fixture.allFacts(); fixture.problem(fixture.replace(version, Integer.MAX_VALUE, 9), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); fixture.noPlatformWrites();
    }
}
